    Differential Revision: https://phabricator.services.mozilla.com/D305081

diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 5f97045a66d..bc77edcc67a 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -2854,7 +2854,7 @@ nsresult nsImapMailFolder::ParseAdoptedHeaderLine(const char* aMessageLine,
   // but they never contain partial lines
   const char* str = aMessageLine;
   m_curMsgUid = uid;
-  m_msgParser->SetNewKey(m_curMsgUid);
+  m_msgParser->SetMsgUid(uid);
   // m_envelope_pos, for local folders,
   // is the msg key. Setting this will set the msg key for the new header.

diff --git a/mailnews/imap/src/nsImapService.cpp b/mailnews/imap/src/nsImapService.cpp
index de39ea222c3..a2f341fe224 100644
--- a/mailnews/imap/src/nsImapService.cpp
+++ b/mailnews/imap/src/nsImapService.cpp
@@ -1722,8 +1722,9 @@ nsresult nsImapService::OfflineAppendFromFile(
       // if (NS_SUCCEEDED(rv) && bytesRead > 0)
       msgParser->SetState(nsIMsgParseMailMsgState::ParseHeadersState);
       msgParser->SetNewMsgHdr(newMsgHdr);
-      // set the new key to fake key so the msg hdr will have that for a key
-      msgParser->SetNewKey(fakeKey);
+      // Set the new UID to fake key so the msg hdr will have that for a key.
+      // See https://bugzilla.mozilla.org/show_bug.cgi?id=1806770
+      msgParser->SetMsgUid((ImapUid)fakeKey);
       bool needMoreData = false;
       char* newLine = nullptr;
       uint32_t numBytesInLine = 0;
